          "address": "",
          "geography": "Chicago (the Loop)",
          "precision": "search locator, not surveyed",
          "map_url": "https://www.google.com/maps/search/?api=1&query=Pinkerton%27s%20National%20Detective%20Agency%2C%20Chicago"
