          "name": "Civic Opera House",
          "address": "20 N. Wacker Drive",
          "geography": "20 N. Wacker Drive",
          "precision": "search locator, not surveyed",
          "map_url": "https://www.google.com/maps/search/?api=1&query=Civic%20Opera%20House%2C%2020%20N.%20Wacker%20Drive%2C%20Chicago"
