          "address": "1334 S. Peoria Street",
          "geography": "1334 S. Peoria Street, Near West Side",
          "precision": "search locator, not surveyed",
          "map_url": "https://www.google.com/maps/search/?api=1&query=Meadowmoor%20Dairies%2C%201334%20S.%20Peoria%20Street%2C%20Chicago"
