          "name": "Marion",
          "address": "",
          "geography": "Grant County, Indiana — the courthouse square, the Grant County jail",
          "precision": "search locator, not surveyed",
          "map_url": "https://www.google.com/maps/search/?api=1&query=Marion%2C%20Grant%20County%2C%20Indiana%20%E2%80%94%20the%20courthouse%20square%2C%20the%20Grant%20County%20jail"
