          "name": "Communist Party of Canada headquarters",
          "address": "",
          "geography": "Toronto",
          "precision": "search locator, not surveyed",
          "map_url": "https://www.google.com/maps/search/?api=1&query=Communist%20Party%20of%20Canada%20headquarters%2C%20Toronto"
