          "name": "Federal offices everywhere",
          "address": "",
          "geography": "including Chicago's post office, customs house and Treasury offices",
          "precision": "search locator, not surveyed",
          "map_url": "https://www.google.com/maps/search/?api=1&query=Federal%20offices%20everywhere%2C%20including%20Chicago%27s%20post%20office%2C%20customs%20house%20and%20Treasury%20offices"
