          "address": "",
          "geography": "(Morton Grove/Glenview, standard record)",
          "precision": "search locator, not surveyed",
          "map_url": "https://www.google.com/maps/search/?api=1&query=the%20Dells%20roadhouse%20on%20the%20northwest%20edge%20of%20the%20city%2C%20Chicago"
