          "name": "Michigan Avenue parade",
          "address": "",
          "geography": "(Ohio Street to Soldier Field, 10:00–12:25), then Soldier Field",
          "precision": "search locator, not surveyed",
          "map_url": "https://www.google.com/maps/search/?api=1&query=Michigan%20Avenue%20parade%20%2C%20then%20Soldier%20Field"
