          "name": "Edgewater Drive at Point Place",
          "address": "",
          "geography": "north Toledo",
          "precision": "search locator, not surveyed",
          "map_url": "https://www.google.com/maps/search/?api=1&query=Edgewater%20Drive%20at%20Point%20Place%2C%20north%20Toledo"
