          "address": "",
          "geography": "Livingston County (Coleman)",
          "precision": "search locator, not surveyed",
          "map_url": "https://www.google.com/maps/search/?api=1&query=a%20summer%20cottage%20and%20a%20swamp%20near%20Pinckney%2C%20Livingston%20County%2C%20Chicago"
